{"command": "cd /problem && cat > src/gemm.cu << 'KERNEL_EOF'
#include "gemm.cuh"

#include <cuda_runtime.h>

// Optimized tiled GEMM for A40 (Ampere, sm_86)
// Block: 32x16 = 512 threads -> TILE_N=32, TILE_M=16
// TILE_K=32 for shared memory K-tiles
// Shared memory padded to avoid bank conflicts

#define TILE_M 16
#define TILE_N 32
#define TILE_K 32

// Shared memory layout (padding for bank conflict avoidance):
// As[k][ty] stores A[row+ty, t*TILE_K+k]  ->  32 x 17 (17 cols for padding)
// Bs[tx][k] stores B[t*TILE_K+k, col+tx]  ->  32 x 33 (33 cols for padding)
//
// Bank conflicts avoided because:
// - blockDim.x = 32 (full warp width), so each warp has unique tx values
// - With 17 columns (gcd(17,32)=1):  As bank accesses are conflict-free
// - With 33 columns (33≡1 mod 32, gcd(33,32)=1):  Bs bank accesses are conflict-free
__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE_K][TILE_M + 1];   // 32 x 17
    __shared__ float Bs[TILE_N][TILE_K + 1];   // 32 x 33

    const int row   = blockIdx.y * TILE_M + threadIdx.y;
    const int col   = blockIdx.x * TILE_N + threadIdx.x;
    const int tMax  = (N + TILE_K - 1) / TILE_K;

    float acc = 0.0f;

    for (int t = 0; t < tMax; ++t) {
        // --- Load A tile into shared memory ---
        // As[tx][ty] = A[row+ty, t*TILE_K+tx]
        const int aRow = row;
        const int aCol = t * TILE_K + threadIdx.x;
        if (aRow < N && aCol < N)
            As[threadIdx.x][threadIdx.y] = A[aRow * N + aCol];
        else
            As[threadIdx.x][threadIdx.y] = 0.0f;

        // --- Load B tile into shared memory ---
        // Bs[tx][ty] = B[t*TILE_K+ty, col+tx]
        const int bRow = t * TILE_K + threadIdx.y;
        const int bCol = col;
        if (bRow < N && bCol < N)
            Bs[threadIdx.x][threadIdx.y] = B[bRow * N + bCol];
        else
            Bs[threadIdx.x][threadIdx.y] = 0.0f;

        __syncthreads();

        // --- Inner matmul (register-accumulated) ---
        // Thread (tx,ty): acc += sum_k As[k][ty] * Bs[tx][k]
#pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += As[k][threadIdx.y] * Bs[threadIdx.x][k];
        }

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE_N, TILE_M);       // (32, 16)
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (N + TILE_M - 1) / TILE_M);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
KERNEL_EOF"}

