#define TILE_N 32
#define TILE_K 16

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    // As[k][ty] -- k is loop var (0..15), ty is thread y (0..15)
    // 33 columns: stride 33 is coprime to 32 -> no bank conflicts
    __shared__ float As[TILE_K][TILE_M + 1];  // 16 x 17

    // Bs[k][tx] -- k is loop var (0..15), tx is thread x (0..31)
    // 17 columns: stride 17 is coprime to 32 -> no bank conflicts
    __shared__ float Bs[TILE_K][TILE_N + 1];  // 16 x 33

    const int row   = blockIdx.y * TILE_M + threadIdx.y;
    const int col   = blockIdx.x * TILE_N + threadIdx.x;
