#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

// WMMA-based GEMM for A40 (Ampere)
// Uses FP32 tensor cores for 16x16x16 matmuls
// Block: 16x16 = 256 threads, each thread handles 1 output element
// Each warp does one 16x16 WMMA fragment

#define MMA_FRAG_SIZE 16
#define MMA_K 16

// Fragments for FP32 WMMA
// wmma::fragment<wmma::matrix_a, 16x16x16, float, wmma::row_major>
// wmma::fragment<wmma::matrix_b, 16x16x16, float, wmma::col_major>
// wmma::fragment<wmma::accumulator, 16x16x16, float>

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    // WMMA fragment declarations
    wmma::fragment<wmma::matrix_a,  MMA_FRAG_SIZE, MMA_FRAG_SIZE, MMA_K, 
                   wmma::precision::tf32, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b,  MMA_FRAG_SIZE, MMA_FRAG_SIZE, MMA_K, 
                   wmma::precision::tf32, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, MMA_FRAG_SIZE, MMA_FRAG_SIZE, MMA_K, float> c_frag;

    const int row = blockIdx.y * MMA_FRAG_SIZE + threadIdx.y;
    const int col = blockIdx.x * MMA_FRAG_SIZE + threadIdx.x;
    const int numTiles = (N + MMA_K - 1) / MMA_K;

    // Initialize accumulator
    wmma::fill_fragment(c_frag, 0.0f);

    for (int t = 0; t < numTiles; ++t) {
        // Load A tile (row-major) - the warp loads this
        // wmma::load_matrix_sync handles the loading pattern internally
        wmma::load_matrix_sync(a_frag, 
                               A + row * N + t * MMA_K, 
                               N, 
                               wmma::matrix_layout::row_major);

        // Load B tile (column-major for WMMA)
        wmma::load_matrix_sync(b_frag,
                               B + (t * MMA_K) * N + col,
                               N,
                               wmma::matrix_layout::col_major);

        // Matrix multiply accumulate
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);
    }

    // Store result
    if (row < N && col < N) {
        wmma::store_matrix_sync(C + row * N + col,
                                c_frag,
                                N,
                                wmma::matrix_layout::row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(MMA_FRAG_SIZE, MMA_FRAG_SIZE);  // (16, 16)
    dim3 grid((N + MMA_FRAG_SIZE - 1) / MMA_FRAG_SIZE,
              (N + MMA_FRAG_SIZE - 1) / MMA_FRAG_SIZE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
