{"command": "cd /problem && cat > src/gemm.cu << 'EOF'
#include "gemm.cuh"

#include <cuda_runtime.h>

// Highly-optimized tiled GEMM for A40 (Ampere, sm_86)
//
// Strategy:
// 1. Block: 32x16 = 512 threads -> TILE_N=32, TILE_M=16
//    Each warp has 32 unique tx, same ty (blockDim.x=32)
// 2. TILE_K=32 -> fewer syncs, more FMA per sync
// 3. Tile_M=TILE_K=32 for the B load pattern match
// 4. Register-tiled inner loop for better instruction scheduling
// 5. Bank-conflict-free shared memory

#define TILE_M 32
#define TILE_N 32
#define TILE_K 32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    // Shared memory layout:
    // As[k][ty] -- k loop var, ty thread-y
    // Bs[k][tx] -- k loop var, tx thread-x
    //
    // As: 32 rows (k=0..31), 33 cols (ty=0..31 + 1 pad)
    //     Bank(k,ty) = (k*33+ty)%32 = (k+ty)%32
    //     Loading As[tx][ty]: warp ty fixed, tx=0..31 -> unique banks ✓
    //     Inner As[k][ty]: all threads same ty, broadcast ✓
    //
    // Bs: 32 rows (k=0..31), 33 cols (tx=0..31 + 1 pad)
    //     Bank(k,tx) = (k*33+tx)%32 = (k+tx)%32
    //     Loading Bs[ty][tx]: warp ty fixed, tx=0..31 -> unique banks ✓
    //     Inner Bs[k][tx]: warp tx=0..31, fixed k -> unique banks ✓

    __shared__ float As[TILE_K][TILE_M + 1];   // 32 x 33
    __shared__ float Bs[TILE_K][TILE_N + 1];   // 32 x 33

    const int row   = blockIdx.y * TILE_M + threadIdx.y;
    const int col   = blockIdx.x * TILE_N + threadIdx.x;
    const int tMax  = (N + TILE_K - 1) / TILE_K;

    // Use multiple registers for better scheduling
    float acc1 = 0.0f, acc2 = 0.0f, acc3 = 0.0f, acc4 = 0.0f;

    for (int t = 0; t < tMax; ++t) {
        // Load A tile: As[tx][ty] = A[row+ty, t*TILE_K+tx]
        const int aCol = t * TILE_K + threadIdx.x;
        if (row < N && aCol < N)
            As[threadIdx.x][threadIdx.y] = A[row * N + aCol];
        else
            As[threadIdx.x][threadIdx.y] = 0.0f;

        // Load B tile: Bs[ty][tx] = B[t*TILE_K+ty, col+tx]
        const int bRow = t * TILE_K + threadIdx.y;
        if (bRow < N && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[bRow * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        // Inner loop with register blocking
        // Accumulate in 4 separate registers to allow instruction pipelining
        acc1 = 0.0f; acc2 = 0.0f; acc3 = 0.0f; acc4 = 0.0f;
#pragma unroll
        for (int k = 0; k < TILE_K; k += 4) {
            acc1 += As[k + 0][threadIdx.y] * Bs[k + 0][threadIdx.x];
            acc2 += As[k + 1][threadIdx.y] * Bs[k + 1][threadIdx.x];
            acc3 += As[k + 2][threadIdx.y] * Bs[k + 2][threadIdx.x];
            acc4 += As[k + 3][threadIdx.y] * Bs[k + 3][threadIdx.x];
        }
        acc = acc1 + acc2 + acc3 + acc4;

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE_N, TILE_M);  // (32, 32)
    dim3 grid((N + TILE_N - 1) / TILE_N, (N + TILE_M - 1) / TILE_M);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
EOF"}

