#include "gemm.cuh"

#include <cuda_runtime.h>

// Tiled GEMM for A40 (Ampere, sm_86)
// Block: 32x32 = 1024 threads -> TILE_M=TILE_N=TILE_K=32
// Bank-conflict-free shared memory
// Register-tiled inner loop + unrolled K loop for ILP

#define TILE 32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    // As[tx][ty] layout: TILE cols (tx=0..31), TILE rows (ty=0..31)
    // 33 cols for bank conflict avoidance in loading
    __shared__ float As[TILE][TILE + 1];  // 32 x 33

    // Bs[tx][ty] layout: TILE cols (tx=0..31), TILE rows (ty=0..31)
    // 33 cols for bank conflict avoidance
    __shared__ float Bs[TILE][TILE + 1];  // 32 x 33

    const int row   = blockIdx.y * TILE + threadIdx.y;
    const int col   = blockIdx.x * TILE + threadIdx.x;
    const int tMax  = (N + TILE - 1) / TILE;

    // Register accumulators for instruction-level parallelism
    float a1 = 0.0f, a2 = 0.0f, a3 = 0.0f, a4 = 0.0f;
    float acc = 0.0f;

    for (int t = 0; t < tMax; ++t) {
        // Load A: As[tx][ty] = A[row+ty, t*TILE+tx]
        const int aCol = t * TILE + threadIdx.x;
        if (row < N && aCol < N)
            As[threadIdx.x][threadIdx.y] = A[row * N + aCol];
        else
            As[threadIdx.x][threadIdx.y] = 0.0f;

        // Load B: Bs[tx][ty] = B[t*TILE+ty, col+tx]
        const int bRow = t * TILE + threadIdx.y;
        if (bRow < N && col < N)
            Bs[threadIdx.x][threadIdx.y] = B[bRow * N + col];
        else
            Bs[threadIdx.x][threadIdx.y] = 0.0f;

        __syncthreads();

        // Register-blocked inner loop (4-way unrolling)
        a1 = 0.0f; a2 = 0.0f; a3 = 0.0f; a4 = 0.0f;
#pragma unroll
        for (int k = 0; k < TILE; k += 4) {
            // Each chain accesses different shared memory locations
            // As[k+j][ty] and Bs[tx][k+j] for j=0..3
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                float ak = As[k + j][threadIdx.y];
                float bk = Bs[threadIdx.x][k + j];
                if (j == 0) a1 += ak * bk;
                else if (j == 1) a2 += ak * bk;
                else if (j == 2) a3 += ak * bk;
                else a4 += ak * bk;
            }
        }
        acc = a1 + a2 + a3 + a4;

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
EOF

