#include "gemm.cuh"

#include <cuda_runtime.h>

// Tiled GEMM for A40 (sm_86) - TILE=16, software-pipelined
// 16x16 block, 48 warps/SM, software-pipelined K-loop

#define TILE 16

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int row   = blockIdx.y * TILE + threadIdx.y;
    const int col   = blockIdx.x * TILE + threadIdx.x;
    const int tMax  = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    // Load first K-tile
    {
        const int aCol = threadIdx.x;
        if (row < N && aCol < N)
            As[threadIdx.y][threadIdx.x] = A[row * N + aCol];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        const int bRow = threadIdx.y;
        if (bRow < N && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[bRow * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
    }
    __syncthreads();

    // Compute K-tile 0, then for each subsequent tile: load, compute
    for (int t = 0; t < tMax; ++t) {
        // Compute current K-tile
#pragma unroll
        for (int k = 0; k < TILE; ++k)
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];

        // Load next K-tile (if exists)
        if (t + 1 < tMax) {
            const int at = t + 1;
            const int aCol = at * TILE + threadIdx.x;
