{"command": "cd /problem && cat > src/gemm.cu << 'EOF'
#include "gemm.cuh"

#include <cuda_runtime.h>

// Tiled GEMM for A40 (sm_86) - TILE=16
// 16x16 block, 48 warps/SM (max occupancy)
// Optimized: restrict pointers, register blocking, no-bank-conflict layout

#define TILE 16

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int row   = blockIdx.y * TILE + threadIdx.y;
    const int col   = blockIdx.x * TILE + threadIdx.x;
    const int tMax  = (N + TILE - 1) / TILE;

    // Register accumulators for better ILP
    float s1 = 0.0f, s2 = 0.0f, s3 = 0.0f, s4 = 0.0f;
    float acc = 0.0f;

    for (int t = 0; t < tMax; ++t) {
        // Load A tile: As[ty][tx] = A[row+ty, t*TILE+tx]
        const int aCol = t * TILE + threadIdx.x;
        if (row < N && aCol < N)
            As[threadIdx.y][threadIdx.x] = A[row * N + aCol];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        // Load B tile: Bs[ty][tx] = B[t*TILE+ty, col+tx]
        const int bRow = t * TILE + threadIdx.y;
        if (bRow < N && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[bRow * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        // Register-blocked inner loop (4-way unrolling)
        s1 = 0.0f; s2 = 0.0f; s3 = 0.0f; s4 = 0.0f;
#pragma unroll
        for (int k = 0; k < TILE; k += 4) {
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                float tmp = As[threadIdx.y][k + j] * Bs[k + j][threadIdx.x];
                if (j == 0) s1 += tmp;
                else if (j == 1) s2 += tmp;
                else if (j == 2) s3 += tmp;
                else s4 += tmp;
            }
        }
        acc = s1 + s2 + s3 + s4;

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
EOF"}

