{"command": "cd /problem && cat > src/gemm.cu << 'EOF'
#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

// Hybrid approach: WMMA for FMA throughput + shared memory tiling
// Block: 16x16 = 256 threads, TILE_M=TILE_N=TILE_K=16
// Each warp does 1 WMMA operation on a 16x16x16 fragment

#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    // WMMA fragments per warp
    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K,
                   float, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K,
                   float, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> c_frag;

    const int row   = blockIdx.y * WMMA_M + threadIdx.y;
    const int col   = blockIdx.x * WMMA_N + threadIdx.x;
    const int tMax  = (N + WMMA_K - 1) / WMMA_K;

    wmma::fill_fragment(c_frag, 0.0f);

    for (int t = 0; t < tMax; ++t) {
        // Load A (row-major): the warp handles this
        wmma::load_matrix_sync(a_frag,
                               A + row * N + t * WMMA_K,
                               N,
                               wmma::matrix_layout::row_major);

        // Load B (column-major): the warp handles this
        wmma::load_matrix_sync(b_frag,
                               B + (t * WMMA_K) * N + col,
                               N,
                               wmma::matrix_layout::col_major);

        // WMMA: C += A * B
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);
    }

    if (row < N && col < N)
        wmma::store_matrix_sync(C + row * N + col,
                                c_frag,
                                N,
                                wmma::matrix_layout::row_major);
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(WMMA_M, WMMA_N);  // (16, 16)
    dim3 grid((N + WMMA_M - 1) / WMMA_M, (N + WMMA_N - 1) / WMMA_N);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
EOF"}

