// Tiled GEMM for A40 (sm_86) - TILE=16
// 1D shared memory with bank conflict avoidance via padding

#define TILE 16
#define AS_ROWS TILE  // As layout: As[k][ty] -> TILE rows, TILE cols padded
#define AS_COLS (TILE + 1)  // 17 cols for bank avoidance (17 coprime to 32)
#define BS_ROWS TILE  // Bs layout: Bs[k][tx] -> TILE rows, TILE cols padded  
#define BS_COLS (TILE + 1)  // 17 cols for bank avoidance

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[AS_ROWS][AS_COLS];  // 16 x 17
    __shared__ float Bs[BS_ROWS][BS_COLS];  // 16 x 17

    const int row   = blockIdx.y * TILE + threadIdx.y;
    const int col   = blockIdx.x * TILE + threadIdx.x;
    const int tMax  = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < tMax; ++t) {
        // Load A tile: As[tx][ty] = A[row+ty, t*TILE+tx]
        const int aCol = t * TILE + threadIdx.x;
        if (row < N && aCol < N)
            As[threadIdx.x][threadIdx.y] = A[row * N + aCol];
        else
            As[threadIdx.x][threadIdx.y] = 0.0f;

        // Load B tile: Bs[ty][tx] = B[t*TILE+ty, col+tx]
        const int bRow = t * TILE + threadIdx.y;
        if (bRow < N && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[bRow * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        // Inner matmul: acc += sum_k As[k][ty] * Bs[k][tx]
#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[k][threadIdx.y] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
EOF"}

