#include "gemm.cuh"

#include <cuda_runtime.h>

// Tiled GEMM for A40 (sm_86) - TILE=16
// Aggressively unrolled inner loop, restrict pointers

#define TILE 16

__forceinline__ __device__ void inner_loop(const float* __restrict__ a, 
                                            const float* __restrict__ b, 
                                            float& acc, int tx, int ty) {
#pragma unroll
    for (int k = 0; k < TILE; ++k) {
        acc += a[k] * b[k];
    }
}

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int row   = blockIdx.y * TILE + threadIdx.y;
    const int col   = blockIdx.x * TILE + threadIdx.x;
    const int tMax  = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < tMax; ++t) {
        const int aCol = t * TILE + threadIdx.x;
        const int bRow = t * TILE + threadIdx.y;

        As[threadIdx.y][threadIdx.x] = 
            (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
        Bs[threadIdx.y][threadIdx.x] = 
            (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;

        __syncthreads();

        // Use pointers for faster inner loop access
        const float* as_ptr = As[threadIdx.y];
        const float* bs_ptr = Bs[threadIdx.x];
#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += as_ptr[k] * bs_ptr[k];
        }

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

